<?php session_start();require_once "db.php";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("SELECT id,name,password FROM users WHERE email=?");$s->bind_param("s",$_POST["email"]);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($_POST["password"],$u["password"])){$_SESSION["uid"]=$u["id"];$_SESSION["uname"]=$u["name"];header("Location: orders.php");exit;}$msg="Invalid login."; } ?>
